LEFT JOIN [ref].[SalesAllocationStatus] p1 ON b.[SalesAllocationStatusKey] = p1.[SalesAllocationStatusKey]
LEFT JOIN [dim].[Plant] p2 ON b.[FulfillmentPlantKey] = p2.[PlantKey]
LEFT JOIN [ref].[Country] p3 ON p2.[CountryKey] = p3.[CountryKey]
LEFT JOIN [ref].[Region] p4 ON p3.[RegionKey] = p4.[RegionKey]
LEFT JOIN [ref].[Continent] p5 ON p4.[ContinentKey] = p5.[ContinentKey]
